def is_power_of_two(num):
    if num <= 0:
        return False
    return (num & (num - 1) == 0)

def solve_problem(N_limit, X_limit):
    solutions = []
    for n in range(3, N_limit + 1):
        # We must have x > n, so start x from n + 1
        for x in range(n + 1, X_limit + 1):
            try:
                val = x**n + x - 2
                if is_power_of_two(val):
                    # Find k such that 2^k = val
                    k = val.bit_length() - 1
                    solutions.append((x, n, k))
            except OverflowError:
                # Stop searching further for this n if calculation overflows standard integer types
                break
    return solutions

